syntax:
struct BitFieldExample {
    unsigned int flag : 1;  // Allocates 1 bit; implementation-defined packing and alignment
    unsigned int value : 7;  // Allocates 7 bits; may be packed into the same integer as 'flag'
    unsigned int reserved : 24;  // Allocates 24 bits; compiler may pad or align as needed
};  // Note: The total size is implementation-defined; e.g., might be 4 bytes if packed into a 32-bit int

code_example:
#include <iostream>
#include <cstdint>
struct BitFieldExample {
    unsigned int flag : 1;  // Bit 0
    unsigned int value : 7;  // Bits 1-7
    unsigned int reserved : 24;  // Bits 8-31 (if packed)
};

int main() {
    BitFieldExample ex;
    ex.flag = 1;  // Set the flag bit
    ex.value = 42;  // Set the value bits
    std::cout << "Size of struct: " << sizeof(ex) << " bytes" << std::endl;  // Likely 4 bytes on 32-bit systems
    return 0;
}
